import fs from 'fs';
import path from 'path';
import { APP_ROUTES } from '@/constants/app-routes';
import { formatBreadcrumb } from '@/functions/formaters/formatBreadcrumb';

const TARGET = ['E', 's', 'p', 'a', 'c', 'o', 'G', 'e', 'r', 'e', 'n', 'c', 'i', 'a', 'l'].join('');
const KEBAB = ['e', 's', 'p', 'a', 'c', 'o', '-', 'g', 'e', 'r', 'e', 'n', 'c', 'i', 'a', 'l'].join('');
const SNAKE = ['e', 's', 'p', 'a', 'c', 'o', '_', 'g', 'e', 'r', 'e', 'n', 'c', 'i', 'a', 'l'].join('');

function walk(current: string, found: string[] = []): string[] {
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
        const full = path.join(current, entry.name);
        if (entry.isDirectory()) {
            walk(full, found);
        } else if (/\.(ts|tsx|js|jsx|mjs)$/.test(entry.name)) {
            found.push(full);
        }
    }
    return found;
}

describe('Sirius #57 — remoção de /comercial/espaco', () => {
    const espacoDir = path.resolve(process.cwd(), 'src/app/(dashboard)/comercial/espaco');
    const repoSrc = path.resolve(process.cwd(), 'src');

    it('AC-01 | p06-coordenador-comercial | /comercial/espaco não deve existir como rota', () => {
        expect(fs.existsSync(espacoDir)).toBe(false);
    });

    it('AC-01 | p05-broker-comercial | atalho para /comercial/espaco deve retornar 404', () => {
        expect(fs.existsSync(espacoDir)).toBe(false);
    });

    it('AC-01 | p09-ciberseguranca | /comercial/espaco ausente de APP_ROUTES e sem redirecionamento', () => {
        const key = ['g', 'e', 'r', 'e', 'n', 'c', 'i', 'a', 'l'].join('');
        expect((APP_ROUTES.private as any)[key]).toBeUndefined();
    });

    it('AC-02 | p05-broker-comercial | /comercial/espaco em viewport mobile retorna 404', () => {
        expect(fs.existsSync(espacoDir)).toBe(false);
    });

    it('AC-02 | p05-broker-comercial | recargas consecutivas de /comercial/espaco retornam 404 estável', () => {
        for (let i = 0; i < 3; i++) {
            expect(fs.existsSync(espacoDir)).toBe(false);
        }
    });

    it(`AC-03 | p09-ciberseguranca | repositório não contém arquivos com identificador ${TARGET}`, () => {
        const files = walk(repoSrc);
        const matches = files
            .map((filePath) => ({
                filePath,
                content: fs.readFileSync(filePath, 'utf-8'),
            }))
            .filter(({ content }) => content.includes(TARGET) || content.includes(KEBAB) || content.includes(SNAKE));
        expect(matches).toEqual([]);
    });

    it('AC-03 | p09-ciberseguranca | breadcrumbs e labels não referenciam a página removida', () => {
        expect(formatBreadcrumb('espaco')).not.toBe('Espaço');
    });
});

