import { expect } from '@jest/globals';
import { formatBreadcrumb } from '@/functions/formaters/formatBreadcrumb';
import { QueryKeys } from '@/constants/query-keys';
import { QueryClient } from '@tanstack/react-query';
import {
    buildAppHeaderCrumbs,
    collapseAppHeaderCrumbs,
    extractAppHeaderPathEntities,
    isEntityIdSegment,
    maskEntityIdHint,
    type AppHeaderCrumbItem,
} from '../build-app-header-crumbs';
import {
    resolveParteNomeFromQueryCache,
    buildAppHeaderParteNomeObserverOptions,
} from '../resolve-app-header-parte-nome';

const SAMPLE_DUE_UUID = 'a1b2c3d4-e5f6-7890-abcd-ef1234567890';
const SAMPLE_OFICIO_UUID = '31cea495-1234-5678-9abc-def012345678';
const SAMPLE_PARTE_UUID = 'b2c3d4e5-f6a7-8901-bcde-f12345678901';

describe('formatBreadcrumb (Fase 2 — Title Case)', () => {
    it('maps canonical segments without ALL CAPS', () => {
        expect(formatBreadcrumb('juridico')).toBe('Jurídico');
        expect(formatBreadcrumb('due-diligence-2.0')).toBe('Pedências e Repactuações');
        expect(formatBreadcrumb('pos-aquisicao')).toBe('Pós-aquisição');
        expect(formatBreadcrumb('liquidacao-cessao')).toBe('Liquidação / Cessão');
    });

    it('falls back to Title Case with PT accents for unknown slugs', () => {
        expect(formatBreadcrumb('situacao-financeira')).toBe('Situação Financeira');
        expect(formatBreadcrumb('meu_segmento')).toBe('Meu Segmento');
        expect(formatBreadcrumb('calendario-operacional')).toBe('Calendário Operacional');
    });

    it('covers high-traffic editorial segments (inventory, not partial v1)', () => {
        expect(formatBreadcrumb('oficios')).toBe('Ofícios');
        expect(formatBreadcrumb('repactuacoes')).toBe('Repactuações');
        expect(formatBreadcrumb('operacoes-financeiras')).toBe('Operações financeiras');
        expect(formatBreadcrumb('politica-de-privacidade')).toBe('Política de privacidade');
        expect(formatBreadcrumb('gerencial-broker')).toBe('Gerencial Broker');
        expect(formatBreadcrumb('pos-precatorios')).toBe('Pós-precatórios');
    });

    it('never forces uppercase on the whole label', () => {
        const label = formatBreadcrumb('due-diligence-2.0');
        expect(label).not.toBe(label.toLocaleUpperCase('pt-BR'));
        expect(label).toBe('Pedências e Repactuações');
    });
});

describe('isEntityIdSegment / maskEntityIdHint', () => {
    it('detects UUID and long numeric ids', () => {
        expect(isEntityIdSegment(SAMPLE_DUE_UUID)).toBe(true);
        expect(isEntityIdSegment('123456')).toBe(true);
        expect(isEntityIdSegment('due-diligence-2.0')).toBe(false);
        expect(isEntityIdSegment('42')).toBe(false);
    });

    it('masks long ids for tooltips', () => {
        expect(maskEntityIdHint(SAMPLE_DUE_UUID)).toBe('a1b2c3d4…');
        expect(maskEntityIdHint('short')).toBe('short');
    });
});

describe('buildAppHeaderCrumbs', () => {
    it('builds Title Case crumbs for Due 2.0 path', () => {
        const crumbs = buildAppHeaderCrumbs(`/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}`, {
            dueNomeCredor: 'Maria Silva',
        });

        expect(crumbs).toHaveLength(3);
        expect(crumbs.every((c) => c.kind === 'crumb')).toBe(true);

        const labels = crumbs
            .filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb')
            .map((c) => c.label);

        expect(labels).toEqual(['Jurídico', 'Pedências e Repactuações', 'Maria Silva']);
        expect(labels.join(' ')).not.toMatch(/[A-F0-9]{8}-[A-F0-9]{4}/i);
    });

    it('uses short Due placeholder when UUID has no cache name', () => {
        const crumbs = buildAppHeaderCrumbs(`/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}`);
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;

        expect(current.label).toBe('Due');
        expect(current.label).not.toMatch(SAMPLE_DUE_UUID);
        expect(current.hint).toBe('a1b2c3d4…');
        expect(current.isCurrent).toBe(true);
    });

    it('resolves ofício credor on novo_broker flow', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/novo_broker/${SAMPLE_OFICIO_UUID}/proposta`, {
            oficioCredor: 'João Credor',
        });
        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        const ofícioCrumb = human.find((c) => c.href.includes(SAMPLE_OFICIO_UUID));
        expect(ofícioCrumb?.label).toBe('João Credor');
    });

    it('resolves ofício credor on /crm/broker/{id} (cockpit)', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/broker/${SAMPLE_OFICIO_UUID}`, {
            oficioCredor: 'Sérgio Antônio Chemale Madeira',
        });
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Sérgio Antônio Chemale Madeira');
        expect(current.label).not.toBe('Item');
    });

    it('broker v4: crumb /crm/broker/{id} aponta para a gaveta no início', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/broker/${SAMPLE_OFICIO_UUID}/memoria`, {
            oficioCredor: 'Espólio de Carlyle Prates',
            brokerOficioHref: (id) => `/crm/broker/inicio?op=${id}`,
        });

        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        const extratoCrumb = human.find((c) => c.label === 'Espólio de Carlyle Prates');
        expect(extratoCrumb?.href).toBe(`/crm/broker/inicio?op=${SAMPLE_OFICIO_UUID}`);
        expect(extratoCrumb?.isCurrent).toBe(false);
        expect(human[human.length - 1].label).toBe('Memória');
    });

    it('sem override, crumb /crm/broker/{id} mantém href clássico', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/broker/${SAMPLE_OFICIO_UUID}/memoria`, {
            oficioCredor: 'Espólio de Carlyle Prates',
        });

        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        const extratoCrumb = human.find((c) => c.label === 'Espólio de Carlyle Prates');
        expect(extratoCrumb?.href).toBe(`/crm/broker/${SAMPLE_OFICIO_UUID}`);
    });

    it('override não afeta outros pais de ofício (gerencial-broker)', () => {
        const crumbs = buildAppHeaderCrumbs(
            `/crm/gerencial-broker/${SAMPLE_OFICIO_UUID}/memoria`,
            {
                oficioCredor: 'Credor Gerencial',
                brokerOficioHref: (id) => `/crm/broker/inicio?op=${id}`,
            },
        );

        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        const extratoCrumb = human.find((c) => c.label === 'Credor Gerencial');
        expect(extratoCrumb?.href).toBe(`/crm/gerencial-broker/${SAMPLE_OFICIO_UUID}`);
    });

    it('uses Ofício placeholder on broker path without cache (never Item)', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/broker/${SAMPLE_OFICIO_UUID}`);
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Ofício');
        expect(current.label).not.toBe('Item');
        expect(current.hint).toBe('31cea495…');
    });

    it('uses Ofício placeholder without ofício cache on novo_broker', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/novo_broker/${SAMPLE_OFICIO_UUID}`);
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Ofício');
        expect(current.hint).toBe('31cea495…');
    });

    it('resolves ofício credor on /crm/gerencial-broker/{id}', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/gerencial-broker/${SAMPLE_OFICIO_UUID}`, {
            oficioCredor: 'João Credor',
        });
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('João Credor');
        expect(current.label).not.toBe('Item');
    });

    it('uses Ofício placeholder on /crm/gerencial-broker/{id} without cache (never Item)', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/gerencial-broker/${SAMPLE_OFICIO_UUID}`);
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Ofício');
        expect(current.label).not.toBe('Item');
        expect(current.hint).toBe('31cea495…');
    });

    it('resolves ofício credor on /crm/oficios/{id}', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/oficios/${SAMPLE_OFICIO_UUID}`, {
            oficioCredor: 'Maria Credora',
        });
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Maria Credora');
        expect(current.label).not.toBe('Item');
    });

    it('uses Ofício placeholder on /crm/oficios/{id} without cache (never Item)', () => {
        const crumbs = buildAppHeaderCrumbs(`/crm/oficios/${SAMPLE_OFICIO_UUID}`);
        const current = crumbs[crumbs.length - 1];
        expect(current.kind).toBe('crumb');
        if (current.kind !== 'crumb') return;
        expect(current.label).toBe('Ofício');
        expect(current.label).not.toBe('Item');
        expect(current.hint).toBe('31cea495…');
    });

    it('makes root linkable and only last crumb current', () => {
        const crumbs = buildAppHeaderCrumbs('/juridico/due-diligence-2.0');
        expect(crumbs).toHaveLength(2);
        const [root, current] = crumbs as AppHeaderCrumbItem[];
        expect(root.isRoot).toBe(true);
        expect(root.isCurrent).toBe(false);
        expect(root.href).toBe('/juridico');
        expect(current.isCurrent).toBe(true);
        expect(current.isRoot).toBe(false);
    });

    it('collapses depth > 3 into ellipsis + last two', () => {
        const crumbs = buildAppHeaderCrumbs(
            `/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}/situacao-juridica/certidoes`,
            { dueNomeCredor: 'Credor X' },
        );

        expect(crumbs.some((c) => c.kind === 'ellipsis')).toBe(true);
        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        expect(human).toHaveLength(3);
        expect(human[0].label).toBe('Jurídico');
        expect(human[human.length - 1].label).toBe('Certidões');
        expect(human[human.length - 1].isCurrent).toBe(true);

        const ellipsis = crumbs.find((c) => c.kind === 'ellipsis');
        expect(ellipsis?.kind).toBe('ellipsis');
        if (ellipsis?.kind !== 'ellipsis') return;
        expect(ellipsis.omitted.length).toBeGreaterThan(0);
        expect(ellipsis.omitted.some((o) => o.label === 'Credor X')).toBe(true);
    });

    it('deep certidões route: parte nome visible, never Item/UUID as current parent', () => {
        const path = `/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}/situacao-juridica/${SAMPLE_PARTE_UUID}/certidoes`;
        const crumbs = buildAppHeaderCrumbs(path, {
            dueNomeCredor: 'Maria Credora',
            parteNome: 'João Cedente',
        });

        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        expect(human.map((c) => c.label)).toEqual(['Jurídico', 'João Cedente', 'Certidões']);
        expect(human.every((c) => !isEntityIdSegment(c.label))).toBe(true);
        expect(human.some((c) => c.label === 'Item')).toBe(false);

        const ellipsis = crumbs.find((c) => c.kind === 'ellipsis');
        expect(ellipsis?.kind).toBe('ellipsis');
        if (ellipsis?.kind !== 'ellipsis') return;
        expect(ellipsis.omitted.some((o) => o.label === 'Maria Credora')).toBe(true);
    });

    it('deep certidões without parte cache uses Parte placeholder (not Item)', () => {
        const path = `/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}/situacao-juridica/${SAMPLE_PARTE_UUID}/certidoes`;
        const crumbs = buildAppHeaderCrumbs(path, { dueNomeCredor: 'Maria Credora' });
        const human = crumbs.filter((c): c is AppHeaderCrumbItem => c.kind === 'crumb');
        const parteCrumb = human.find((c) => c.href.includes(SAMPLE_PARTE_UUID));
        expect(parteCrumb?.label).toBe('Parte');
        expect(parteCrumb?.hint).toBe('b2c3d4e5…');
    });
});

describe('extractAppHeaderPathEntities', () => {
    it('extracts extratoId from /crm/broker/{id}', () => {
        expect(extractAppHeaderPathEntities(`/crm/broker/${SAMPLE_OFICIO_UUID}`)).toEqual({
            extratoId: SAMPLE_OFICIO_UUID,
            dueId: null,
            parteId: null,
        });
    });

    it('ignores static broker children', () => {
        expect(extractAppHeaderPathEntities('/crm/broker/propostas-digitais')).toEqual({
            extratoId: null,
            dueId: null,
            parteId: null,
        });
    });

    it('extracts extratoId from /crm/gerencial-broker/{id}', () => {
        expect(extractAppHeaderPathEntities(`/crm/gerencial-broker/${SAMPLE_OFICIO_UUID}`)).toEqual({
            extratoId: SAMPLE_OFICIO_UUID,
            dueId: null,
            parteId: null,
        });
    });

    it('extracts extratoId from /crm/oficios/{id}', () => {
        expect(extractAppHeaderPathEntities(`/crm/oficios/${SAMPLE_OFICIO_UUID}`)).toEqual({
            extratoId: SAMPLE_OFICIO_UUID,
            dueId: null,
            parteId: null,
        });
    });

    it('ignores static gerencial-broker children', () => {
        expect(extractAppHeaderPathEntities('/crm/gerencial-broker')).toEqual({
            extratoId: null,
            dueId: null,
            parteId: null,
        });
    });

    it('extracts dueId + parteId from certidões deep path', () => {
        const path = `/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}/situacao-juridica/${SAMPLE_PARTE_UUID}/certidoes`;
        expect(extractAppHeaderPathEntities(path)).toEqual({
            extratoId: null,
            dueId: SAMPLE_DUE_UUID,
            parteId: SAMPLE_PARTE_UUID,
        });
    });

    it('extracts parteId from detalhes-parte', () => {
        const path = `/juridico/due-diligence-2.0/${SAMPLE_DUE_UUID}/integra/detalhes-parte/${SAMPLE_PARTE_UUID}`;
        expect(extractAppHeaderPathEntities(path).parteId).toBe(SAMPLE_PARTE_UUID);
    });
});

describe('resolveParteNomeFromQueryCache', () => {
    it('reads titularProcessos cache regardless of tipoTitular suffix', () => {
        const client = new QueryClient();
        client.setQueryData(
            [QueryKeys.dueDiligence.titularProcessos, SAMPLE_PARTE_UUID, 'cedente'],
            {
                tipoTitular: 'cedente',
                titular: { id: SAMPLE_PARTE_UUID, nome: 'Ana Parte', cpf: '000' },
            },
        );
        expect(resolveParteNomeFromQueryCache(client, SAMPLE_PARTE_UUID, SAMPLE_DUE_UUID)).toBe(
            'Ana Parte',
        );
    });

    it('buildAppHeaderParteNomeObserverOptions covers titular + detalhes keys', () => {
        const opts = buildAppHeaderParteNomeObserverOptions(SAMPLE_PARTE_UUID, SAMPLE_DUE_UUID);
        expect(opts).toHaveLength(4);
        expect(opts.every((o) => o.enabled === false)).toBe(true);
        expect(opts.map((o) => o.queryKey?.[0])).toEqual([
            QueryKeys.dueDiligence.titularProcessos,
            QueryKeys.dueDiligence.titularProcessos,
            QueryKeys.dueDiligence.detalhesPartePessoa,
            QueryKeys.dueDiligence.detalhesPartePessoa,
        ]);
    });
});

describe('collapseAppHeaderCrumbs', () => {
    it('keeps lists of length <= 3 intact', () => {
        const input: AppHeaderCrumbItem[] = [
            {
                kind: 'crumb',
                key: '/a',
                href: '/a',
                label: 'A',
                isRoot: true,
                isCurrent: false,
            },
            {
                kind: 'crumb',
                key: '/a/b',
                href: '/a/b',
                label: 'B',
                isRoot: false,
                isCurrent: true,
            },
        ];
        expect(collapseAppHeaderCrumbs(input)).toEqual(input);
    });
});

