import { formatBreadcrumb } from '@/functions/formaters/formatBreadcrumb';

/** Max human crumbs before collapsing the middle into an ellipsis. */
export const APP_HEADER_MAX_VISIBLE_CRUMBS = 3;

/** Chars kept in masked entity-id tooltip (`a1b2c3d4…`). */
export const APP_HEADER_ENTITY_ID_HINT_PREFIX_LENGTH = 8;

/** Min digit count to treat a numeric path segment as an entity id. */
export const APP_HEADER_LONG_NUMERIC_ID_MIN_DIGITS = 6;

const UUID_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const LONG_NUMERIC_ID_RE = new RegExp(
    `^\\d{${APP_HEADER_LONG_NUMERIC_ID_MIN_DIGITS},}$`,
);

const DUE_PARENT_SEGMENTS = new Set([
    'due-diligence-2.0',
    'due-diligence',
    'liquidacao-cessao',
]);
const OFICIO_PARENT_SEGMENTS = new Set([
    'broker',
    'novo_broker',
    'gerencial-broker',
    'oficios',
]);
/** UUID under these parents = pessoa/cedente/parte in Due deep routes. */
const PARTE_PARENT_SEGMENTS = new Set(['situacao-juridica', 'detalhes-parte']);

export type AppHeaderCrumbContext = {
    /** `nome_credor` from Due Diligence 2.0 detail cache. */
    dueNomeCredor?: string | null;
    /** `credor` from ofício detail cache (`/crm/broker/{id}`, `/crm/novo_broker/{id}`, `/crm/gerencial-broker/{id}`, `/crm/oficios/{id}`). */
    oficioCredor?: string | null;
    /**
     * Nome da pessoa/cedente/vínculo em rotas profundas Due
     * (`…/situacao-juridica/{pessoaId}/…`, `…/detalhes-parte/{parteId}`).
     */
    parteNome?: string | null;
    /**
     * Override do href do crumb `/crm/broker/{id}` — no cutover Broker v4 o
     * detalhe da operação é a gaveta em `/crm/broker/inicio?op={id}`, não a
     * página clássica.
     */
    brokerOficioHref?: (extratoId: string) => string;
};

export type AppHeaderCrumbItem = {
    kind: 'crumb';
    key: string;
    href: string;
    label: string;
    /** Optional native/tooltip hint (e.g. truncated UUID). */
    hint?: string;
    isRoot: boolean;
    isCurrent: boolean;
};

export type AppHeaderEllipsisItem = {
    kind: 'ellipsis';
    key: string;
    omitted: Array<{ href: string; label: string; hint?: string }>;
};

export type AppHeaderCrumb = AppHeaderCrumbItem | AppHeaderEllipsisItem;

export type AppHeaderPathEntities = {
    extratoId: string | null;
    dueId: string | null;
    /** Pessoa/cedente/parte UUID in deep Due routes (certidões, processos, detalhes-parte). */
    parteId: string | null;
};

export function isEntityIdSegment(segment: string): boolean {
    return UUID_RE.test(segment) || LONG_NUMERIC_ID_RE.test(segment);
}

export function maskEntityIdHint(id: string): string {
    if (id.length <= APP_HEADER_ENTITY_ID_HINT_PREFIX_LENGTH) return id;
    return `${id.slice(0, APP_HEADER_ENTITY_ID_HINT_PREFIX_LENGTH)}…`;
}

function isOficioParentSegment(parent: string): boolean {
    return OFICIO_PARENT_SEGMENTS.has(parent);
}

function isDueParentSegment(parent: string): boolean {
    return DUE_PARENT_SEGMENTS.has(parent);
}

function isParteParentSegment(parent: string): boolean {
    return PARTE_PARENT_SEGMENTS.has(parent);
}

/**
 * Extracts entity IDs from AppHeader-relevant pathnames (no fetch).
 * Used by AppHeader to look up React Query cache keys.
 */
export function extractAppHeaderPathEntities(pathname: string): AppHeaderPathEntities {
    const segments = pathname.split('/').filter(Boolean);
    const empty: AppHeaderPathEntities = {
        extratoId: null,
        dueId: null,
        parteId: null,
    };

    if (segments.length === 0) return empty;

    if (
        segments[0] === 'crm' &&
        isOficioParentSegment(segments[1] ?? '') &&
        isEntityIdSegment(segments[2] ?? '')
    ) {
        empty.extratoId = segments[2] ?? null;
    }

    if (segments[0] === 'juridico' && isDueParentSegment(segments[1] ?? '')) {
        if (isEntityIdSegment(segments[2] ?? '')) {
            empty.dueId = segments[2] ?? null;
        }

        const situacaoIdx = segments.indexOf('situacao-juridica');
        if (situacaoIdx >= 0 && isEntityIdSegment(segments[situacaoIdx + 1] ?? '')) {
            empty.parteId = segments[situacaoIdx + 1] ?? null;
        }

        const detalhesIdx = segments.indexOf('detalhes-parte');
        if (detalhesIdx >= 0 && isEntityIdSegment(segments[detalhesIdx + 1] ?? '')) {
            empty.parteId = segments[detalhesIdx + 1] ?? null;
        }
    }

    return empty;
}

type ResolvedLabel = {
    label: string;
    hint?: string;
};

function resolveEntityPlaceholder(
    segments: string[],
    index: number,
    id: string,
): ResolvedLabel {
    const parent = index > 0 ? segments[index - 1] : '';
    const hint = maskEntityIdHint(id);

    if (isDueParentSegment(parent)) {
        return { label: 'Due', hint };
    }
    if (isOficioParentSegment(parent)) {
        return { label: 'Ofício', hint };
    }
    if (isParteParentSegment(parent)) {
        return { label: 'Parte', hint };
    }
    return { label: 'Item', hint };
}

function resolveSegmentLabel(
    segment: string,
    segments: string[],
    index: number,
    ctx: AppHeaderCrumbContext,
): ResolvedLabel {
    if (!isEntityIdSegment(segment)) {
        return { label: formatBreadcrumb(segment) };
    }

    const parent = index > 0 ? segments[index - 1] : '';

    if (isDueParentSegment(parent) && ctx.dueNomeCredor?.trim()) {
        return { label: ctx.dueNomeCredor.trim() };
    }

    if (isOficioParentSegment(parent) && ctx.oficioCredor?.trim()) {
        return { label: ctx.oficioCredor.trim() };
    }

    if (isParteParentSegment(parent) && ctx.parteNome?.trim()) {
        return { label: ctx.parteNome.trim() };
    }

    return resolveEntityPlaceholder(segments, index, segment);
}

function buildFullCrumbs(
    pathname: string,
    ctx: AppHeaderCrumbContext,
): AppHeaderCrumbItem[] {
    const segments = pathname.split('/').filter(Boolean);
    if (segments.length === 0) return [];

    return segments.map((segment, index) => {
        let href = `/${segments.slice(0, index + 1).join('/')}`;
        if (
            ctx.brokerOficioHref &&
            index === 2 &&
            segments[0] === 'crm' &&
            segments[1] === 'broker' &&
            isEntityIdSegment(segment)
        ) {
            href = ctx.brokerOficioHref(segment);
        }
        const { label, hint } = resolveSegmentLabel(segment, segments, index, ctx);
        return {
            kind: 'crumb' as const,
            key: href,
            href,
            label,
            hint,
            isRoot: index === 0,
            isCurrent: index === segments.length - 1,
        };
    });
}

/**
 * Collapses middle crumbs when depth exceeds {@link APP_HEADER_MAX_VISIBLE_CRUMBS}.
 * Pattern: first + ellipsis(omitted) + last two → at most 3 human crumbs.
 */
export function collapseAppHeaderCrumbs(
    crumbs: AppHeaderCrumbItem[],
    maxVisible: number = APP_HEADER_MAX_VISIBLE_CRUMBS,
): AppHeaderCrumb[] {
    if (crumbs.length <= maxVisible) return crumbs;

    const first = crumbs[0];
    const lastTwo = crumbs.slice(-2);
    const omitted = crumbs.slice(1, -2).map(({ href, label, hint }) => ({
        href,
        label,
        hint,
    }));

    return [
        first,
        {
            kind: 'ellipsis',
            key: `ellipsis:${omitted.map((o) => o.href).join('|')}`,
            omitted,
        },
        ...lastTwo,
    ];
}

/**
 * Builds curated AppHeader breadcrumbs from a pathname + optional entity labels.
 * - Title Case / canonical map (no ALL CAPS)
 * - UUID/long IDs resolve to entity name or short placeholder
 * - Depth > 3 collapses middle into ellipsis with omitted links
 *
 * @see docs/app-header-breadcrumbs.md
 */
export function buildAppHeaderCrumbs(
    pathname: string,
    ctx: AppHeaderCrumbContext = {},
): AppHeaderCrumb[] {
    return collapseAppHeaderCrumbs(buildFullCrumbs(pathname, ctx));
}
